31	\centering
32	\small
33	\begin{tabular}{p{2.4cm}p{3.9cm}p{4.7cm}}
34	\toprule
35	\textbf{阶段} & \textbf{目标} & \textbf{注意事项} \\
36	\midrule
37	SFT & 学会基本动作语法与任务格式 & 防止只记模板，忽视长链路泛化 \\
38	Search-augmented & 提升探索质量与成功轨迹占比 & 控制推理预算，避免过度采样 \\
39	RL / policy update & 对齐终局成功率和鲁棒性 & 防止 reward hacking 与分布偏移 \\
40	\bottomrule
41	\end{tabular}
42	\caption{Web Agent 常见训练组合路径}
43	\end{table}
